const slice150 = createSlice({
  name: 'slice150',
  initialState: { list: [] as Item150[], status: 'idle' },
  reducers: {
    added(state, action: PayloadAction<Item150>) {
      state.list.push(action.payload)
    },
    cleared(state) {
      state.list = []
    },
    prepared: {
      prepare(label: string) {
        return { payload: { id: 'x', label150: label } as Item150 }
      },
      reducer(state, action: PayloadAction<Item150>) {
        state.list.push(action.payload)
      },
    },
  },
  selectors: {
    selectList: (state) => state.list,
  },
})
export const reducer150 = slice150.reducer
export const actions150 = slice150.actions
export const selectors150 = slice150.selectors

